using System.Collections;
using System.IO;
using UnityEditor;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
using System.Collections.Generic;
[InitializeOnLoad] public static class StorybookExperienceReminderValidation{
 const string Out="output/experience-reminder/";static bool running;static double started;
 static StorybookExperienceReminderValidation(){EditorApplication.update+=Tick;EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredEditMode&&SessionState.GetBool("REMINDER_QA",false)){SessionState.SetBool("REMINDER_QA",false);SessionState.SetBool("MONSTER_QA_DISABLE_SAVE",false);running=false;}};}
 static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;if(!EditorApplication.isPlayingOrWillChangePlaymode&&File.Exists(Out+"validate.request")){File.Delete(Out+"validate.request");File.WriteAllText(Out+"validation.txt","");SessionState.SetBool("REMINDER_QA",true);SessionState.SetBool("MONSTER_QA_DISABLE_SAVE",true);EditorApplication.isPlaying=true;}if(EditorApplication.isPlaying&&SessionState.GetBool("REMINDER_QA",false)&&!running&&GameManager.single&&GameplayCanvas.single){running=true;started=EditorApplication.timeSinceStartup;GameManager.single.StartCoroutine(Run());}if(running&&EditorApplication.timeSinceStartup-started>180){Check(false,"timeout");EditorApplication.isPlaying=false;}}
 static void Check(bool ok,string s)=>File.AppendAllText(Out+"validation.txt",(ok?"PASS ":"FAIL ")+s+"\n");
 static void Shot(string name){var t=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(Out+name+".png",t.EncodeToPNG());Object.Destroy(t);}
 static StorybookExperienceReminder Fresh(){var g=Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(StorybookExperienceReminderAuthoring.Path));var v=g.GetComponent<StorybookExperienceReminder>();v.cooldownHours=0;return v;}
 static IEnumerator Run(){var intro=Object.FindAnyObjectByType<CursedBookIntro>(FindObjectsInactive.Include);while(intro&&intro.gameObject.activeSelf)yield return null;yield return new WaitForSecondsRealtime(1);var gc=GameplayCanvas.single;var gm=GameManager.single;gc.CancelInvoke("TryShowingXpBoosterNotification");gc.xpBoosterNotification.SetActive(false);gc.dailyCherriesPop.SetActive(false);TutorialManager.single.automatic=false;TutorialManager.single.view.Hide();for(int i=0;i<9;i++)if(!gm.HasSeenThis("Tutorial-"+i))gm.thingsSeenPermanent.Add("Tutorial-"+i);gm.isBoostedXPActive=false;
 Check(gc.experienceReminder&&gc.xpBoosterNotification==gc.experienceReminder.gameObject,"Scene replacement installed");
 foreach(var size in new[]{new Vector2Int(1080,1920),new Vector2Int(768,1024),new Vector2Int(720,1440)}){StorybookEquipmentValidation.Resolution(size.x,size.y);yield return new WaitForSecondsRealtime(.3f);var ui=Fresh();Check(ui.TryShow(),"Eligible home reminder "+size);yield return new WaitForSecondsRealtime(.5f);foreach(var button in new[]{ui.open,ui.close}){var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,button.transform.position)},hits);Check(hits.Count>0&&hits[0].gameObject.GetComponentInParent<Button>()==button,"Button raycast "+button.name+size);}yield return new WaitForEndOfFrame();Shot("reminder-"+size.x+"x"+size.y);ui.close.onClick.Invoke();Check(!ui.gameObject.activeSelf&&!ui.group.blocksRaycasts&&!ui.TryShow(),"Dismiss releases input and suppresses repeated reminders");Object.Destroy(ui.gameObject);}
 var v=Fresh();gm.isBoostedXPActive=true;gm.xpBoostEndTime=System.DateTime.Now.AddMinutes(10);Check(!v.TryShow(),"No reminder while boost active");gm.isBoostedXPActive=false;var state=gm.gameState;gm.gameState=Assets.Scripts.Game.Enum.GameStateType.MAP;Check(!v.TryShow(),"No reminder on map");gm.gameState=state;gc.homeUI.settingsUI.Open();Check(!v.TryShow(),"No reminder over settings");gc.homeUI.settingsUI.Close();v.lifetime=.8f;Check(v.TryShow(),"Can show after blocking condition clears");yield return new WaitForSecondsRealtime(1);Check(!v.gameObject.activeSelf,"Automatic timeout");Object.Destroy(v.gameObject);
 v=Fresh();float balance=gm.premiumCurrency;v.TryShow();yield return new WaitForSecondsRealtime(.4f);v.open.onClick.Invoke();yield return new WaitForSecondsRealtime(2.5f);Check(gc.experienceUI.gameObject.activeSelf&&!v.gameObject.activeSelf,"Open routes to new experience page");Check(gm.premiumCurrency==balance&&!gm.HasActiveXpBoost,"Opening neither purchases nor grants boost");gc.experienceUI.Close();yield return new WaitForSecondsRealtime(2);Object.Destroy(v.gameObject);StorybookEquipmentValidation.Resolution(1080,1920);File.AppendAllText(Out+"validation.txt","DONE\n");EditorApplication.isPlaying=false;}
}
